pf-code-prime.code:
import sys

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def main():
    s = sys.stdin.read().strip()
    if s:
        n = int(s)
        print("Yes" if is_prime(n) else "No")

if __name__ == "__main__":
    main()

